use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct State {
    next_ticket: usize,
    serving: usize,
}

struct Semaphore {
    state: Mutex<State>,
    changed: Condvar,
}

impl Semaphore {
    fn new() -> Self {
        Self {
            state: Mutex::new(State {
                next_ticket: 0,
                serving: 0,
            }),
            changed: Condvar::new(),
        }
    }

    fn acquire(&self) -> Permit<'_> {
        let mut state = self.state.lock().unwrap();
        let ticket = state.next_ticket;
        state.next_ticket += 1;

        while state.serving != ticket {
            state = self.changed.wait(state).unwrap();
        }

        Permit { s: self }
    }
}

struct Permit<'a> {
    s: &'a Semaphore,
}

impl Drop for Permit<'_> {
    fn drop(&mut self) {
        let mut state = self.s.state.lock().unwrap();
        state.serving += 1;
        self.s.changed.notify_all();
    }
}

fn activate(s: Arc<Semaphore>) {
